import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { MlShowcase } from "@/components/dashboard/ml-showcase";
import { formatDifference, formatError, loadShowcase, resetShowcaseCache, type Showcase } from "@/lib/data/showcase";

// The payload generated by research/ml-showcase/analysis.py from the real artifacts.
const PAYLOAD = JSON.parse(readFileSync(join(__dirname, "..", "public", "ml", "showcase.json"), "utf-8")) as Showcase;

const okFetch = () => vi.fn(() => Promise.resolve(new Response(JSON.stringify(PAYLOAD), { status: 200 })));

beforeEach(() => resetShowcaseCache());
afterEach(() => vi.unstubAllGlobals());

describe("showcase payload", () => {
  it("holds the reproduced 2023 validation results, not test results", () => {
    expect(PAYLOAD.evaluated_on).toMatch(/validation/);
    expect(PAYLOAD.evaluated_on).toMatch(/2023/);
    expect(PAYLOAD.tasks.a.lightgbm.value).toBeCloseTo(0.10095, 4);
    expect(PAYLOAD.tasks.a.beats_best_baseline).toBe(false);
    expect(PAYLOAD.tasks.b.lightgbm.value).toBeCloseTo(0.06058, 4);
    expect(PAYLOAD.tasks.b.beats_best_baseline).toBe(true);
    expect(PAYLOAD.tasks.d_pax.lightgbm.value).toBeCloseTo(0.22242, 4);
    expect(PAYLOAD.tasks.d_pax.bias.value).toBeLessThan(-0.1);
    for (const task of Object.values(PAYLOAD.tasks)) {
      for (const row of task.monthly) expect(row.month.startsWith("2023-")).toBe(true);
    }
  });

  it("contains only aggregates: no more than a few hundred sampled points per task", () => {
    for (const task of Object.values(PAYLOAD.tasks)) expect(task.scatter.length).toBeLessThanOrEqual(400);
  });
});

describe("formatting", () => {
  it("shows WAPE as a percentage and load-factor MAE in points", () => {
    expect(formatError({ metric: "WAPE" }, 0.1009535)).toBe("10.10%");
    expect(formatError({ metric: "seat-weighted MAE" }, 0.0605802)).toBe("6.06 pts");
    expect(formatDifference({ metric: "WAPE" }, -0.0020721)).toBe("-0.21 pts of WAPE");
    expect(formatError({ metric: "WAPE" }, null)).toBe("—");
  });
});

describe("loadShowcase", () => {
  it("requests the file once and retries after a failure", async () => {
    const failing = vi.fn(() => Promise.resolve(new Response("", { status: 404 })));
    await expect(loadShowcase(failing)).rejects.toThrow("could not be loaded (404)");
    const fetchOk = okFetch();
    await loadShowcase(fetchOk);
    await loadShowcase(fetchOk);
    expect(fetchOk).toHaveBeenCalledTimes(1);
    expect(fetchOk).toHaveBeenCalledWith("/ml/showcase.json", expect.anything());
  });
});

describe("ML Studio showcase", () => {
  it("states that Model A has no conclusive gain over its baseline", async () => {
    vi.stubGlobal("fetch", okFetch());
    render(<MlShowcase />);
    expect(await screen.findByText("10.10%")).toBeInTheDocument();
    expect(screen.getByText("10.30%")).toBeInTheDocument();
    expect(screen.getByText(/Not conclusive: interval includes zero/)).toBeInTheDocument();
    expect(screen.getByText(/The baseline remains the method of record/)).toBeInTheDocument();
    expect(screen.getByRole("link", { name: /Technical report/ })).toHaveAttribute("href", "/ml/report.pdf");
  });

  it("shows Model D's gain, its bias and its failure six months ahead", async () => {
    vi.stubGlobal("fetch", okFetch());
    render(<MlShowcase />);
    fireEvent.click(await screen.findByRole("tab", { name: "D · Route passengers" }));
    expect(await screen.findByText("22.24%")).toBeInTheDocument();
    expect(screen.getByText(/Conclusive: interval excludes zero/)).toBeInTheDocument();
    expect(screen.getByText(/At 6 months ahead, LightGBM is worse than the best baseline/)).toBeInTheDocument();
    expect(screen.getByText(/Systematic under-forecast: bias -12.2%/)).toBeInTheDocument();
  });

  it("switches horizon and example without generating any prediction", async () => {
    vi.stubGlobal("fetch", okFetch());
    render(<MlShowcase />);
    await screen.findByText("10.10%");
    fireEvent.click(screen.getByRole("tab", { name: "3 mo ahead" }));
    expect(screen.getByRole("tab", { name: "3 mo ahead" })).toHaveAttribute("aria-selected", "true");
    fireEvent.click(screen.getByRole("tab", { name: "Worst" }));
    const card = screen.getByText("Retrospective hits and misses").closest("section") as HTMLElement;
    expect(within(card).getByText(PAYLOAD.tasks.a.examples?.worst.entity as string)).toBeInTheDocument();
    // There is no form: the page shows verified out-of-sample predictions only.
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
    expect(screen.queryByRole("spinbutton")).not.toBeInTheDocument();
  });

  it("shows Model B in percentage points", async () => {
    vi.stubGlobal("fetch", okFetch());
    render(<MlShowcase />);
    fireEvent.click(await screen.findByRole("tab", { name: "B · Seat occupancy" }));
    await waitFor(() => expect(screen.getByText("6.06 pts")).toBeInTheDocument());
    expect(screen.getByText("6.54 pts")).toBeInTheDocument();
  });

  it("shows an error with retry when the file is missing", async () => {
    vi.stubGlobal("fetch", vi.fn(() => Promise.resolve(new Response("", { status: 404 }))));
    render(<MlShowcase />);
    expect(await screen.findByRole("alert")).toHaveTextContent("could not be loaded");
    expect(screen.getByRole("button", { name: /retry/i })).toBeInTheDocument();
  });
});


describe("audited methodological explanations", () => {
  it("distinguishes selection validation, final refit, and the partially exposed test", async () => {
    vi.stubGlobal("fetch", okFetch());
    render(<MlShowcase />);
    await screen.findByText("10.10%");
    expect(screen.getByText(/not fully blind/)).toBeInTheDocument();
    expect(screen.getByText(/selection-stage models/)).toBeInTheDocument();
    expect(screen.getByText(/not future prediction intervals/)).toBeInTheDocument();
    expect(screen.getByText(/not additional independent passengers or flights/)).toBeInTheDocument();
  });

  it("discloses v1 D missing targets without rewriting its historical validation score", async () => {
    vi.stubGlobal("fetch", okFetch());
    render(<MlShowcase />);
    fireEvent.click(await screen.findByRole("tab", { name: "D · Route passengers" }));
    expect(await screen.findByText("22.24%")).toBeInTheDocument();
    expect(screen.getByText(/four globally missing source months were treated as zero targets/)).toBeInTheDocument();
    expect(screen.getByText(/frozen models and the 2023 scores shown here are unchanged/)).toBeInTheDocument();
  });

  it("uses signed seat-weighted occupancy bias in points, not the historical relative ratio", async () => {
    vi.stubGlobal("fetch", okFetch());
    render(<MlShowcase />);
    fireEvent.click(await screen.findByRole("tab", { name: "B · Seat occupancy" }));
    expect(await screen.findByText("-0.05 pts")).toBeInTheDocument();
    expect(screen.getByText("Bias, seat-weighted")).toBeInTheDocument();
    expect(screen.getByText(/This is not RPK \/ ASK/)).toBeInTheDocument();
    expect(PAYLOAD.tasks.b.seat_weighted_bias?.value).toBeLessThan(0);
    expect(PAYLOAD.tasks.b.bias.value).toBeGreaterThan(0);
  });
});
